  world = makeWorld(); net = buildNet(P.K); net.world = world; refresh(net);
  sweep = 0; acc = 0; hist.V.length = hist.D.length = hist.I.length = 0;
  lastTravel = lastRej = lastAtt = 0;
  record(); draw();
}
function sweepNet(N, etaFrac){ // one activation per corner, in random order
  const eta = etaFrac * N.s, I = N.ivs.slice();
  for (let i = I.length - 1; i > 0; i--){
    const j = (rand() * (i + 1)) | 0;
    [I[i], I[j]] = [I[j], I[i]];
  }
  for (const v of I) activateVertex(N, v, eta);
}
function doSweep(){
  if (sweep >= P.rounds) return;
  if (P.live){ world.step(); refresh(net); }
  sweepNet(net, P.eta);
  sweep++; record();
  if (sweep >= P.rounds){ running = false; document.getElementById("bRun").textContent = "Run"; }
}
function record(){
  const c = net.count, m = net.m; let s = 0, mx = 0;
  for (let i = 0; i < m; i++){ s += c[i]; if (c[i] > mx) mx = c[i]; }
  const mean = s / m; let v = 0; for (let i = 0; i < m; i++) v += (c[i] - mean) ** 2; v /= m;
  let dmax = 0, unb = 0;
  for (const [a, b, L, R] of net.edges){ const d = Math.abs(c[L] - c[R]); if (d > dmax) dmax = d; if (d > 1) unb++; }
  let iso = 1; for (let i = 0; i < m; i++){ const p = perim(net, i); iso = Math.min(iso, 4 * Math.PI * area(net, i) / (p * p)); }
  sweepTravel = net.travel - lastTravel; lastTravel = net.travel;
  sweepRej = net.rejected - lastRej; lastRej = net.rejected;
  sweepAtt = net.attempts - lastAtt; lastAtt = net.attempts;
  current = { s, mean, v, mx, dmax, unb: unb / net.edges.length, iso };
  push(hist.V, v); push(hist.D, dmax); push(hist.I, iso);
}
